"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4702],{8915(e){e.exports=JSON.parse('{"title":"\ub514\uc790\uc774\ub108 \ub610\ud55c \uae30\uc220\uc801 \uc18c\uc591\uc744 \uac16\ucdb0\uc57c \ud55c\ub2e4. \uadf8\ub807\ub2e4\uba74 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub294?","date":"2026-03-12","coverUrl":"/kudzu-based-bench/assets/notion/0ea47e2e7be84540.png","html":"<h1 data-notion-block-id=\\"319e548d-8a8e-802e-8e86-d5042b689bfc\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"31ee548d-8a8e-805e-997b-c37772e59dd5\\" id=\\"31ee548d-8a8e-805e-997b-c37772e59dd5\\">\ub514\uc790\uc774\ub108 \ub610\ud55c \uae30\uc220\uc801 \uc18c\uc591\uc744 \uac16\ucdb0\uc57c \ud55c\ub2e4. \uadf8\ub807\ub2e4\uba74 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub294?</h2><a href=\\"https://www.doc.cc/articles/craft-crisis\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.doc.cc/articles/craft-crisis</a><p data-notion-block-id=\\"31ee548d-8a8e-80c4-9980-f5145ae853ea\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/1f3e548d-8a8e-8063-b8ed-f6bef2f275d2#1f3e548d-8a8e-80cf-a0f1-d24b16bd78e1\\">Figma site \uc0ac\ud0dc</a>\uc640 \uc5ec\ub7ec AI \ub3c4\uad6c\uc758 \ub4f1\uc7a5\uc740 \ub514\uc790\uc774\ub108\uc5d0\uac8c \uae30\uc220\uc801 \uc18c\uc591\uc744 \uc694\uad6c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub294 \ube44\ub2e8 \ub514\uc790\uc774\ub108\uc5d0\uac8c\ub9cc \uad6d\ud55c\ub41c \uc774\uc57c\uae30\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790 \uc5ed\uc2dc \ub9c8\ucc2c\uac00\uc9c0\uc785\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \ub514\uc790\uc778, \uae30\ud68d, \ube44\uc988\ub2c8\uc2a4 \uc758\uc0ac\uacb0\uc815\uc5d0 \uc801\uadf9\uc801\uc73c\ub85c \ucc38\uc5ec\ud574\uc57c \ud568\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub354 \ub098\uc544\uac00, \ud654\uba74 \ub4a4\uc5d0 \uac10\ucdb0\uc9c4 \ubc31\uc5d4\ub4dc\uc640 \uc778\ud504\ub77c\uc758 \uc81c\uc57d \uc0ac\ud56d\uc744 \uc774\ud574\ud558\uc5ec \ud300\uc5d0 \uc62c\ubc14\ub978 \ubc29\ud5a5\uc744 \uc81c\uc2dc\ud558\uace0, \ub2e4\ub978 \ub3d9\ub8cc\ub098 AI\uac00 \uc791\uc131\ud55c \ucf54\ub4dc \uc18d\uc5d0\uc11c \ud504\ub860\ud2b8\uc5d4\ub4dc \uc0dd\ud0dc\uacc4 \ud2b9\uc720\uc758 \uc218\ub9ce\uc740 \uc81c\uc57d\uc0ac\ud56d\uc744 \uc608\ub9ac\ud558\uac8c \ubd84\uc11d\ud558\uace0 \uac80\uc99d\ud574 \ub0bc \uc218 \uc788\uc5b4\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"319e548d-8a8e-80be-b606-dfd9cebc6966\\" id=\\"319e548d-8a8e-80be-b606-dfd9cebc6966\\">React Aria\ub294 \uc65c \ub124\uc774\ud2f0\ube0c <code>&#x3C;dialog></code>\ub97c \uc4f0\uc9c0 \uc54a\uc744\uae4c</h2><a href=\\"https://github.com/adobe/react-spectrum/discussions/9696#discussioncomment-15942257\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/adobe/react-spectrum/discussions/9696#discussioncomment-15942257</a><p data-notion-block-id=\\"319e548d-8a8e-80d2-bc42-d5c843f15b8f\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/2afe548d-8a8e-80ae-99f2-d8d66f5a43a2#2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\"><code>&#x3C;dialog></code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/2afe548d-8a8e-80ae-99f2-d8d66f5a43a2#2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\">\ub294 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubaa8\ub450 \uc9c0\uc6d0</a>\ud558\ub294\ub370\ub3c4, \uc65c React Aria\uac19\uc740 Headless \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\uc9c0, \uadf8\ub9ac\uace0 \ucd5c\uc2e0 HTML, CSS \uae30\ub2a5\uc774 \uc544\uc9c1\uc740 \ub110\ub9ac \uc801\uc6a9\ud558\uae30\uc5d4 \uc2dc\uae30\uc0c1\uc870\uc778\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4(ex. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-80d9-9daf-fbdd34207391\\">sonner \uc81c\uc791\uae30. \uadf8\ub9ac\uace0 \ub9c8\uc8fc\uce5c \ubb38\uc81c\ub4e4</a>).</p><h2 data-notion-block-id=\\"319e548d-8a8e-8033-8568-e77ed92ca509\\" id=\\"319e548d-8a8e-8033-8568-e77ed92ca509\\"><code>&#x3C;Activity/></code>\ub97c \ud1b5\ud574 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 Video \uc2dc\uccad \uacbd\ud5d8 \uc81c\uacf5</h2><a href=\\"https://www.mux.com/blog/react-is-changing-the-game-for-streaming-apps-with-the-activity-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.mux.com/blog/react-is-changing-the-game-for-streaming-apps-with-the-activity-component</a><p data-notion-block-id=\\"31ee548d-8a8e-809c-bc20-f58c155c2361\\">React 19.2\uc5d0 \uc0c8\ub85c \ub098\uc628 <code>&#x3C;Activity/></code>\ub97c \ud1b5\ud574 Video player\uac00 \uac00\ub824\uc84c\uc744 \uacbd\uc6b0\uc5d0 Video \uc2dc\uccad \uacbd\ud5d8\uc744 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ubc29\uc2dd\uc73c\ub85c \uc9c4\ud589\ub418\ub3c4\ub85d \uc5b4\ub5bb\uac8c \uad6c\ud604\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Video\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4, DOM \uc0c1\ud0dc\ub97c \uc800\uc7a5\ud558\uace0 \ub2e4\uc2dc \uc7ac\uac1c\ud558\ub294\ub370\uc5d0 \uc544\uc8fc \uc801\ud569\ud55c \uae30\ub2a5\uc73c\ub85c\uc11c \uc54c\uc544\ub450\uba74 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/304e548d-8a8e-802a-9994-c2dccff3d80a#305e548d-8a8e-80df-987b-f71fea6f9efe\\">React\uc758 \uc885\ub8cc \uc560\ub2c8\uba54\uc774\uc158 \ubb38\uc81c</a>\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-8099-8c8b-ff77f75cf7b6\\" id=\\"31ee548d-8a8e-8099-8c8b-ff77f75cf7b6\\">7\ub144\uac04\uc758 TypeScript \ub9c8\uc774\uadf8\ub808\uc774\uc158, \uc5b4\ub5bb\uac8c \uc9c4\ud589\ud588\ub294\uac00</h2><a href=\\"https://www.patreon.com/posts/seven-years-to-typescript-152144830\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.patreon.com/posts/seven-years-to-typescript-152144830</a><p data-notion-block-id=\\"319e548d-8a8e-8078-8ea4-f1f22c2883d1\\">7\ub144\uac04 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc9c4\ud589\ud558\uba74\uc11c \uc801\uc6a9\ud55c \uc138 \uac00\uc9c0 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud558\uba74\uc11c \uc7a5\ub2e8\uc744 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uac00\uc7a5 \uc8fc\ubaa9\ud560\ub9cc\ud55c AI\ub97c \ud1b5\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc790\uc138\ud788 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/2b7e548d-8a8e-8097-bf24-f20f9aaf3bc7#2bce548d-8a8e-80f2-942f-daed2f7240f4\\">Enzyme\uc5d0\uc11c RTL\ub85c, \uacc4\ud68d\uc801\uc73c\ub85c, \uc790\ub3d9\uc73c\ub85c \ubc14\uafb8\uae30</a>\ub610\ud55c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc124\uacc4\ud558\uace0 \uc5b4\ub5bb\uac8c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc774\ub04c\uc5b4\uac14\ub294\uc9c0 \uc790\uc138\ud558\uac8c \uc18c\uac1c\ud558\ubbc0\ub85c \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-80ae-8ca7-e825a07c4356\\" id=\\"31ee548d-8a8e-80ae-8ca7-e825a07c4356\\">AI \ucc44\ud305\uae30\ub2a5\uc744 \ub9cc\ub4e4 \ub54c \ud544\uc694\ud55c UX</h2><a href=\\"https://medium.com/doctolib/building-reliable-ai-chat-on-mobile-01015d74422e\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/doctolib/building-reliable-ai-chat-on-mobile-01015d74422e</a><p data-notion-block-id=\\"31ee548d-8a8e-8046-9076-c5336109e94e\\">\uae30\ubcf8\uc801\uc778 \ucc44\ud305 \uae30\ub2a5\uc744 \ub9cc\ub4e4 \ub54c\uc640 \ub2e4\ub974\uac8c AI \ucc44\ud305 \uae30\ub2a5\uc740 \uc5b4\ub5a4 UX\ub97c \ub2f4\uc544\uc57c \ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c UX\ub97c \uad6c\ud604\ud558\ub294\ub370 \ubb34\uc5c7\uc774 \ud544\uc694\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. React Native \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0, Tanstack Query\ub97c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, UX \uad6c\ud604 \ubc29\uc2dd\uacfc Tanstack Query\uc758 \uc0ac\uc6a9\ubc95\uc740 \uc6f9 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\ub3c4 \uc801\uc6a9\ub418\ubbc0\ub85c AI \ucc44\ud305 UX\uc5d0 \uad00\uc2ec\uc774 \uc788\ub2e4\uba74 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"319e548d-8a8e-806c-9f20-e84208791085\\" id=\\"319e548d-8a8e-806c-9f20-e84208791085\\">JavaScript-only DRM\uc740 \uc758\ubbf8\uac00 \uc5c6\ub2e4</h2><a href=\\"https://www.therantydev.com/javascript-drms-are-stupid\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.therantydev.com/javascript-drms-are-stupid</a><p data-notion-block-id=\\"31ee548d-8a8e-80dc-b325-f4bda76e188c\\">JS-only DRM\uc744 \ub9ac\ubc84\uc2a4 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\uc744 \ud558\uba74\uc11c \ud558\ub4dc\uc6e8\uc5b4 \uae30\ubc18 DRM\uc774 \uc544\ub2c8\ub77c\uba74 DRM \ubcf4\uc548\uc774 \uc758\ubbf8 \uc5c6\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. DRM\uc758 \uae30\ubcf8\uacfc JS-only DRM\uc744 \ub9ac\ubc84\uc2a4 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\ud558\ub294 \uae00\uc774\ub77c \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \uc9c0\uc2dd\uacfc\ub294 \uc57d\uac04 \uac70\ub9ac\uac00 \uc788\uc9c0\ub9cc, \uae30\ubcf8\uc801\uc73c\ub85c \uc6f9 \ube0c\ub77c\uc6b0\uc800 \ud658\uacbd\uc774\ub77c\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \ubcf4\uc548 \ud55c\uacc4\ub97c \uc54c\uace0 \uc544\ud0a4\ud14d\uccd0\ub9c1\ud560 \ub54c \uc8fc\uc758\ud574\uc57c \ud568\uc744 \ub2e4\uc2dc \uc0c1\uae30\uc2dc\ucf1c\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"319e548d-8a8e-8095-954c-f0dd952fdfb3\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"319e548d-8a8e-80ea-8814-c440da3b4137\\" id=\\"319e548d-8a8e-80ea-8814-c440da3b4137\\">\ubd07 \uac80\uc0ac UI \ub9ac\ub514\uc790\uc778, \uc5b4\ub290 \uac83\uc774 \ud544\uc694\ud560\uae4c</h2><a href=\\"https://blog.cloudflare.com/the-most-seen-ui-on-the-internet-redesigning-turnstile-and-challenge-pages/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/the-most-seen-ui-on-the-internet-redesigning-turnstile-and-challenge-pages/</a><p data-notion-block-id=\\"31ee548d-8a8e-8057-8701-e809aa9f5808\\">\uac00\uc7a5 \ub9ce\uc774 \ub9c8\uc8fc\uce58\uace0, \uac00\uc7a5 \uc2eb\uc5b4\ud558\ub294 UI/UX\uc778 \ubd07 \uac80\uc0ac UI\uc5d0\uc11c \uc5b4\ub290 \ubc29\uc2dd\uc73c\ub85c \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc744 \uc88b\uac8c \ud560\uc9c0 \uc124\uacc4\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub290 \ubd80\ubd84\uc5d0\uc11c\uc758 \uc811\uadfc\uc131 \uc900\uc218\ub97c \ud588\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"319e548d-8a8e-807c-a012-eefbad356cae\\" id=\\"319e548d-8a8e-807c-a012-eefbad356cae\\">RSC \ub80c\ub354\ub9c1 \uc911 \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud55c\ub2e4\uba74</h2><a href=\\"https://twofoldframework.com/blog/error-rendering-with-rsc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://twofoldframework.com/blog/error-rendering-with-rsc</a><p data-notion-block-id=\\"31ee548d-8a8e-8075-babd-d7dd8f5cdd2e\\">RSC \ub80c\ub354\ub9c1 \uc911 \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c RSC / SSR / CSR \ud658\uacbd\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud558\ub294\uc9c0 \uc0c1\uc138\ud558\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. RSC \ub80c\ub354\ub9c1\uc744 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \ubcf4\ud1b5 \ub2e4\ub8e8\ubbc0\ub85c \uc9c1\uc811 \ucc98\ub9ac\ud558\ub294 \uacbd\uc6b0\ub294 \uc801\uc9c0\ub9cc, \uc54c\uc544\ub450\uba74 \uc88b\uc744\ub4ef\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-8014-8beb-cf7d6b6b0fb5\\" id=\\"31ee548d-8a8e-8014-8beb-cf7d6b6b0fb5\\">\uaca9\ub9ac\ub294 \ubb34\uc5c7\uc774\uace0, WASM\uc740 \uc5b4\ub290 \uc218\uc900\uc758 \\"\uaca9\ub9ac\\"\ub97c \uc81c\uacf5\ud558\ub294\uac00?</h2><a href=\\"https://www.shayon.dev/post/2026/52/lets-discuss-sandbox-isolation/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.shayon.dev/post/2026/52/lets-discuss-sandbox-isolation/</a><h2 data-notion-block-id=\\"319e548d-8a8e-80f1-bd72-fb367f5bb60e\\" id=\\"319e548d-8a8e-80f1-bd72-fb367f5bb60e\\">React Fiber\ub294 \uc65c \uc0dd\uaca8\ub0ac\uc744\uae4c?</h2><a href=\\"https://inside-react.vercel.app/blog/understanding-why-react-fiber-exists\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://inside-react.vercel.app/blog/understanding-why-react-fiber-exists</a><h2 data-notion-block-id=\\"319e548d-8a8e-8044-88f2-d02cecff3f2d\\" id=\\"319e548d-8a8e-8044-88f2-d02cecff3f2d\\">\uc65c WASM\uc740 \uc544\uc9c1 JS\ub97c \ud1b5\ud574\uc11c \uc2e4\ud589\ub418\uc5b4\uc57c \ud558\ub294\uac00</h2><a href=\\"https://hacks.mozilla.org/2026/02/making-webassembly-a-first-class-language-on-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hacks.mozilla.org/2026/02/making-webassembly-a-first-class-language-on-the-web/</a><h2 data-notion-block-id=\\"31ee548d-8a8e-80da-9a26-e3b93b5b9c6a\\" id=\\"31ee548d-8a8e-80da-9a26-e3b93b5b9c6a\\">React Native 2025 \uc124\ubb38\uc870\uc0ac \uacb0\uacfc</h2><a href=\\"https://results.2025.stateofreactnative.com/en-US/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://results.2025.stateofreactnative.com/en-US/</a><h1 data-notion-block-id=\\"319e548d-8a8e-80ef-a7a7-cf8bd42d19ed\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://github.com/solidjs/solid/releases/tag/v2.0.0-beta.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/solidjs/solid/releases/tag/v2.0.0-beta.0</a><p data-notion-block-id=\\"319e548d-8a8e-80d1-ae26-dfcf7e2e081a\\">SolidJS 2\ubc84\uc804\uc774 \ub418\uba74\uc11c <code>&#x3C;Suspense></code>\ub97c \ubc84\ub9ac\uace0 \uacc4\uc0b0\uc774 \ubaa8\ub450 Promise\ub97c \ubc18\ud658\ud558\ub3c4\ub85d \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4(\uc544\uc9c1\uc740 \ubca0\ud0c0 \ubc84\uc804\uc774\uc9c0\ub9cc\uc694)</p><a href=\\"https://expo.dev/changelog/sdk-55\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expo.dev/changelog/sdk-55</a><p data-notion-block-id=\\"319e548d-8a8e-80af-a60e-d3da373672e8\\">Expo\uac00 55\ubc84\uc804\uc774 \ub418\uba74\uc11c \uc218\ub9ce\uc740 \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc744 \ucd94\uac00\ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);